// --- DATABASE TYPES ---
interface Agent {
  id: string;
  name: string;
  role: string;
  area: string;
  status: boolean; // active/inactive toggle
  metric: string;
  metricLabel: string;
  tasksToday: number;
  description: string;
  details: string;
  icon: string;
  model: string;
  temperature: number;
  lastActive: string;
  systemPrompt?: string;
  toolsEnabled?: string[];
  memoryScope?: 'global' | 'agent' | 'custom';
  boundaries?: string;
  // Blueprint 07 Governance / Runtime extensions
  agentStatus?: 'template' | 'draft' | 'configuring' | 'ready_to_test' | 'active' | 'needs_review' | 'paused' | 'archived' | 'failed';
  memoryScopeSettings?: Record<string, boolean>;
  toolApprovals?: Record<string, boolean>;
  versionNumber?: number;
  runtimePreset?: 'economico' | 'equilibrado' | 'avancado' | 'long_context' | 'multimodal';
  maxOutputTokens?: number;
  streamingEnabled?: boolean;
  toolCallingEnabled?: boolean;
  structuredOutputEnabled?: boolean;
  fallbackModelId?: string;
  dailyCostLimit?: number;
  installedSkills?: string[]; // keys of installed skills
  channels?: string[];
}

interface Skill {
  id: string;
  name: string;
  description: string;
  code: string;
  category: 'sales' | 'support' | 'docs' | 'ops' | 'custom';
  author: 'System' | 'User' | 'Agent AI';
  createdAt: string;
}

interface Lead {
  id: string;
  name: string;
  company: string;
  value: number;
  stage: 'new' | 'qualifying' | 'meeting' | 'negotiation' | 'closed';
  email: string;
  phone: string;
  score: number;
  lastContact: string;
  nextFollowUp: string;
  suggestion: string;
}

interface Ticket {
  id: string;
  customer: string;
  company: string;
  subject: string;
  status: 'open' | 'urgent' | 'resolved';
  priority: 'low' | 'medium' | 'high';
  category: string;
  date: string;
  messages: Array<{ sender: 'user' | 'agent' | 'system'; text: string; time: string }>;
  sentiment?: 'happy' | 'neutral' | 'angry';
}

interface Appointment {
  id: string;
  title: string;
  customer: string;
  date: string;
  time: string;
  agent: string;
}

interface AuditLog {
  id: string;
  timestamp: string;
  agent: string;
  action: string;
  hash: string;
  riskLevel: 'low' | 'medium' | 'high';
}

export interface ProviderModel {
  provider: string;
  id: string;
  displayName: string;
  family?: string;
  version?: string;
  status: 'current' | 'stable' | 'preview' | 'experimental' | 'legacy' | 'deprecated' | 'retired';
  modalities: Array<'text' | 'image_input' | 'image_output' | 'audio_input' | 'audio_output' | 'video_input' | 'embedding'>;
  capabilities: Array<'chat' | 'completion' | 'reasoning' | 'tool_calling' | 'json_mode' | 'vision' | 'embedding' | 'rerank' | 'code' | 'search' | 'video' | 'music' | 'audio' | 'image_generation'>;
  contextWindow?: number | null;
  maxOutputTokens?: number | null;
  supportsStreaming?: boolean;
  supportsTools?: boolean;
  supportsJsonMode?: boolean;
  supportsVision?: boolean;
  inputPricePer1M?: number | null;
  outputPricePer1M?: number | null;
  currency?: 'USD' | 'BRL';
  source: 'provider_api' | 'fallback_catalog' | 'manual_admin';
  lastVerifiedAt?: string;
  isAvailable: boolean;
  unavailableReason?: string;
  requiresPlan?: 'free' | 'pro' | 'max' | 'business';
  isLatest?: boolean;
  verifiedForKey?: boolean;
}

interface ProviderValidationRun {
  id: string;
  company_id: string;
  provider: string;
  status: 'valid' | 'invalid_key' | 'provider_mismatch' | 'no_models_found' | 'model_not_available' | 'missing_chat_capability' | 'missing_embedding_capability' | 'insufficient_quota' | 'rate_limited' | 'provider_down' | 'unknown_error';
  http_status: number;
  models_found: number;
  selected_model: string;
  selected_model_available: boolean;
  chat_supported: boolean;
  embeddings_supported: boolean;
  streaming_supported: boolean;
  tools_supported: boolean;
  test_generation_passed: boolean;
  test_embedding_passed: boolean;
  error_code: string | null;
  error_message: string | null;
  created_at: string;
}

interface DocumentTrainingTest {
  id: string;
  company_id: string;
  document_id: string;
  status: 'uploaded' | 'extracted' | 'chunked' | 'embedded' | 'indexed' | 'tested' | 'trained';
  generated_questions: string[];
  retrieval_results: Array<{ question: string; chunks_found: number; score: number }>;
  answer_tests: Array<{ question: string; answer: string; has_citation: boolean }>;
  passed: boolean;
  error: string | null;
  created_at: string;
}

interface UiQualityCheck {
  id: string;
  page_key: string;
  no_emojis: boolean;
  no_fake_metrics: boolean;
  has_empty_state: boolean;
  has_loading_state: boolean;
  has_error_state: boolean;
  has_accessibility_labels: boolean;
  notes: string;
  created_at: string;
}

interface SetupGate {
  id: string;
  key: 'workspace_created' | 'provider_validated' | 'model_selected' | 'knowledge_ready' | 'main_agent_configured' | 'main_agent_tested' | 'dashboard_unlocked';
  label: string;
  status: 'locked' | 'pending' | 'in_progress' | 'completed' | 'failed' | 'skipped';
  required: boolean;
  blockingReason?: string;
  actionRequired?: string;
  completedAt?: string;
}

interface SkillTemplate {
  id: string;
  key: string;
  name: string;
  category: string;
  description: string;
  instructions: string;
  inputsSchema: string;
  outputSchema: string;
  requiredTools: string[];
  requiredPermissions: string[];
  compatibleAgentCategories: string[];
  riskLevel: 'low' | 'medium' | 'high';
  exampleRun: string;
  version: string;
  author: string;
}

interface AgentVersion {
  id: string;
  agentId: string;
  versionNumber: number;
  systemPrompt: string;
  toolsEnabled: string[];
  memoryScopeSettings: Record<string, boolean>;
  createdAt: string;
  hash: string;
}

interface Approval {
  id: string;
  agentId: string;
  agentName: string;
  actionType: string;
  actionPayload: string;
  status: 'pending' | 'approved' | 'denied';
  createdAt: string;
}

interface Workflow {
  id: string;
  name: string;
  description: string;
  status: boolean;
  trigger: string;
  steps: string[];
  lastRun: string;
  runsCount: number;
}

interface CronAutomation {
  id: string;
  agentId: string;
  agentName: string;
  name: string;
  schedule: string;
  instruction: string;
  enabled: boolean;
  lastRun: string;
  nextRun: string;
  status: 'success' | 'failure' | 'never';
  logs: string[];
}

interface MemoryDoc {
  id: string;
  name: string;
  title?: string;
  size: string;
  type: string;
  source: string;
  uploadedAt: string;
  category?: string;
  sizeBytes?: number;
  status?: string;
  contentSummary?: string;
}

interface Channel {
  id: string;
  name: string;
  type: string;
  icon: string;
  connected: boolean;
  activeAgents: string[];
  telegramToken?: string;
  telegramBotUsername?: string;
  emailHost?: string;
  emailPort?: string;
  emailUser?: string;
  emailPass?: string;
}

interface TeamMember {
  id: string;
  name: string;
  email: string;
  role: string;
  status: string;
  permissions: string[];
}

interface UserAccount {
  email: string;
  password?: string;
  name: string;
  role: 'user' | 'admin' | 'super_admin';
  plan: 'free' | 'pro' | 'max' | 'business';
}

interface CompanyProfile {
  name: string;
  industry: string;
  size: string;
  goal: string;
  plan?: 'free' | 'pro' | 'max' | 'business';
  tone?: string;
  processes?: string;
  description?: string;
  website?: string;
  toneOfVoice?: string;
  offers?: string;
  forbiddenClaims?: string;
  rules?: string;
  setupComplete: boolean;
  goals90Days?: string;
  authSpendLimit?: string;
  requireApprovalRule?: string;
}


interface ProviderModelOption {
  id: string;
  displayName?: string;
  provider?: string;
  status?: string;
  source?: string;
  isAvailable?: boolean;
  requiresPlan?: string;
  contextWindow?: number;
  supportsTools?: boolean;
  supportsJsonMode?: boolean;
  supportsVision?: boolean;
  unavailableReason?: string;
}

interface ValidatedProviderConnection {
  id: string;
  provider: string;
  selected_chat_model: string;
  key_fingerprint?: string;
  status: string;
}

