  const getProviderKeyUrl = (provider: string) => {
    const urls: Record<string, string> = {
      openai: 'https://platform.openai.com/api-keys',
      anthropic: 'https://console.anthropic.com/settings/keys',
      gemini: 'https://aistudio.google.com/app/apikey',
      openrouter: 'https://openrouter.ai/settings/keys',
      groq: 'https://console.groq.com/keys',
      mistral: 'https://console.mistral.ai/api-keys',
      deepseek: 'https://platform.deepseek.com/api_keys',
      ollama: 'http://localhost:11434'
    };
    return urls[provider] || 'https://docs.lyriq.ai/providers';
  };

  const loadOnboardingProviderModels = async (provider: string) => {
    setOnboardingModelsLoading(true);
    setOnboardingModels([]);
    try {
      const res = await fetch(`/api/providers/${provider}/models`);
      const body = await res.json();
      const models: ProviderModelOption[] = Array.isArray(body.data) ? body.data : [];
      setOnboardingModels(models);
      const firstAvailable = models.find(m => m.isAvailable !== false) || models[0];
      if (firstAvailable) setOnboardingSelectedModel(firstAvailable.id);
    } catch (err: any) {
      setOnboardingApiKeyStatusText(`Não consegui carregar modelos do provider: ${err.message}`);
    } finally {
      setOnboardingModelsLoading(false);
    }
  };

  const handleValidateOnboardingProvider = async () => {
    if (!onboardingApiKey.trim()) {
      addToast('Insira sua chave de API para validar.', 'error');
      return;
    }
    setOnboardingProviderValidating(true);
    setOnboardingApiKeyValidated(false);
    setOnboardingValidatedConnection(null);
    setOnboardingApiKeyStatusText('Validando chave no provider e sincronizando modelos disponíveis...');
    try {
      const res = await fetch(`/api/providers/${onboardingSelectedProvider}/validate-key`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workspaceId: 'workspace_123',
          apiKey: onboardingApiKey,
          modelId: onboardingSelectedModel
        })
      });
      const body = await res.json();
      if (!res.ok || !body.ok) {
        throw new Error(body.error?.message || 'Falha ao validar chave.');
      }
      const models: ProviderModelOption[] = body.data?.models || [];
      const connection = body.data?.connection;
      setOnboardingModels(models.length ? models : onboardingModels);
      if (connection?.selected_chat_model) setOnboardingSelectedModel(connection.selected_chat_model);
      setOnboardingValidatedConnection(connection || null);
      setOnboardingApiKeyValidated(true);
      setOnboardingApiKeyStatusText(`API validada. Provider: ${onboardingSelectedProvider}. Modelo ativo: ${connection?.selected_chat_model || onboardingSelectedModel}. Chave: ${connection?.key_fingerprint || 'mascarada'}.`);
      addToast('API Key validada e modelos sincronizados.', 'success');
    } catch (err: any) {
      setOnboardingApiKeyValidated(false);
      setOnboardingApiKeyStatusText(err.message || 'Chave inválida ou sem permissão para listar modelos.');
      addToast(err.message || 'Chave inválida.', 'error');
    } finally {
      setOnboardingProviderValidating(false);
    }
  };

  useEffect(() => {
    loadOnboardingProviderModels(onboardingSelectedProvider);
    setOnboardingApiKeyValidated(false);
    setOnboardingValidatedConnection(null);
    setOnboardingApiKeyStatusText('');
  }, [onboardingSelectedProvider]);

  const handleInstallAgent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedAgentTemplate) return;

    // Enforce sensitive tool approvals by default
    const approvalsConfig: Record<string, boolean> = {};
    selectedAgentTemplate.defaultTools.concat(selectedAgentTemplate.optionalTools).forEach(tool => {
      const isSensitive = ['deploy', 'delete_data', 'executar_script', 'apagar_dados', 'financial_payout'].some(s => tool.includes(s));
      approvalsConfig[tool] = isSensitive;
    });

    const newAgentItem: Agent = {
      id: selectedAgentTemplate.id.replace('template-', ''),
      name: installAgentName || selectedAgentTemplate.name,
      role: selectedAgentTemplate.role,
      area: selectedAgentTemplate.area,
      status: true,
      model: installModelChoice === 'main' ? 'gemini-1.5-flash' : 'gpt-4o',
      metric: selectedAgentTemplate.area === 'Marketing' ? 'Pautas Criadas' :
              selectedAgentTemplate.area === 'Tecnologia' ? 'Deploys Realizados' :
              selectedAgentTemplate.area === 'Vendas' ? 'Leads Qualificados' :
              selectedAgentTemplate.area === 'Suporte' ? 'SLA Respondido' :
              selectedAgentTemplate.area === 'Financeiro' ? 'Despesas Organizadas' : 'Trilhas Criadas',
      metricLabel: 'Atividade Geral',
      tasksToday: 0,
      description: selectedAgentTemplate.description,
      details: selectedAgentTemplate.description,
      icon: selectedAgentTemplate.icon,
      temperature: 0.4,
      lastActive: 'Agora mesmo',
      systemPrompt: selectedAgentTemplate.agentsMd + `\n\n# Respostas Setup:\n` + 
        Object.entries(installSetupAnswers).map(([q, a]) => `- ${q}: ${a}`).join('\n'),
      toolsEnabled: installAgentTools,
      memoryScope: 'custom',
      boundaries: selectedAgentTemplate.boundaries,
      agentStatus: 'active',
      memoryScopeSettings: installMemoryScopes,
      toolApprovals: approvalsConfig,
      versionNumber: 1,
      installedSkills: installModalSkills
    };

    setAgents(prev => {
      const filtered = prev.filter(a => a.id !== newAgentItem.id);
      return [...filtered, newAgentItem];
    });

    setIsInstallAgentModalOpen(false);
    setSelectedAgentTemplate(null);
    setInstallModalStep(1);
    setInstallSetupAnswers({});
    setInstallMemoryScopes({});
    setInstallModalSkills([]);
    addToast(`Agente ${newAgentItem.name} foi instalado com sucesso a partir do template!`, 'success');
    handleLogAuditEvent(
      'Lyriq Marketplace Engine',
      `Instalou agente "${newAgentItem.name}" (${newAgentItem.role}) a partir do template do marketplace.`,
      'low'
    );
  };

  const handleInstallSkill = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSkillTemplate) return;

    setAgents(prev => {
      return prev.map(agent => {
        if (agent.id === installSkillTargetAgent) {
          const installed = agent.installedSkills || [];
          if (!installed.includes(selectedSkillTemplate.id)) {
            return {
              ...agent,
              installedSkills: [...installed, selectedSkillTemplate.id]
            };
          }
        }
        return agent;
      });
    });

    setIsInstallSkillModalOpen(false);
    setSelectedSkillTemplate(null);
    addToast(`Skill "${selectedSkillTemplate.name}" instalada com sucesso no agente selecionado!`, 'success');
    handleLogAuditEvent('Lyriq Skill Manager', `Instalou playbook de skill: "${selectedSkillTemplate.name}" para o agente ${installSkillTargetAgent}`, 'low');
  };

  const handleValidateProviderKey = async (providerId: string) => {
    const providerObj = providers.find(p => p.id === providerId);
    if (!providerObj) return;
    const rawKey = providerObj.apiKey.trim();
    if (!rawKey) {
      addToast('Insira uma chave de API para validar.', 'error');
      return;
    }

    // Immediately mark as validating
    setProviders(prev => prev.map(p => p.id === providerId ? { ...p, status: 'validating' } : p));
    addToast(`Iniciando validação real do provedor ${providerObj.name}...`, 'info');

    // 1. Format check & Provider mismatch check (Seção 5, 7.2 & 15.2)
    let formatOk = true;
    let mismatchError = false;

    if (providerId === 'openai') {
      if (rawKey.startsWith('gsk_')) {
        mismatchError = true;
      } else if (!rawKey.startsWith('sk-')) {
        formatOk = false;
      }
    } else if (providerId === 'anthropic') {
      if (!rawKey.startsWith('sk-ant-') && !rawKey.startsWith('sk-')) {
        formatOk = false;
      }
    } else if (providerId === 'groq') {
      if (!rawKey.startsWith('gsk_')) {
        formatOk = false;
      }
    } else if (providerId === 'openrouter') {
      if (!rawKey.startsWith('sk-or-') && !rawKey.startsWith('sk-')) {
        formatOk = false;
      }
    }

    if (mismatchError) {
      const errText = 'Esta chave nao parece pertencer ao provedor selecionado. Escolha o provedor correto ou use Custom OpenAI-Compatible.';
      setProviders(prev => prev.map(p => p.id === providerId ? { ...p, status: 'provider_mismatch', lastTested: 'Agora mesmo' } : p));
      addToast(errText, 'error');
      
      const newRun: ProviderValidationRun = {
        id: `run-${Date.now()}`,
        company_id: 'default-co',
        provider: providerId,
        status: 'provider_mismatch',
        http_status: 400,
        models_found: 0,
        selected_model: '',
        selected_model_available: false,
        chat_supported: false,
        embeddings_supported: false,
        streaming_supported: false,
        tools_supported: false,
        test_generation_passed: false,
        test_embedding_passed: false,
        error_code: 'PROVIDER_MISMATCH',
        error_message: errText,
        created_at: new Date().toISOString()
      };
      setProviderValidationRuns(prev => [newRun, ...prev]);
      return;
    }

    if (!formatOk || rawKey.length < 15) {
      const errText = 'Chave de API inválida. Formato incompatível com o provedor.';
      setProviders(prev => prev.map(p => p.id === providerId ? { ...p, status: 'invalid_key', lastTested: 'Agora mesmo' } : p));
      addToast(errText, 'error');

      const newRun: ProviderValidationRun = {
        id: `run-${Date.now()}`,
        company_id: 'default-co',
        provider: providerId,
        status: 'invalid_key',
        http_status: 401,
        models_found: 0,
        selected_model: '',
        selected_model_available: false,
        chat_supported: false,
        embeddings_supported: false,
        streaming_supported: false,
        tools_supported: false,
        test_generation_passed: false,
        test_embedding_passed: false,
        error_code: 'INVALID_KEY_FORMAT',
        error_message: errText,
        created_at: new Date().toISOString()
      };
      setProviderValidationRuns(prev => [newRun, ...prev]);
      return;
    }

    // 2. Perform Real HTTP Validation (Backend validate call)
    try {
      const response = await fetch('/api/providers/validate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          workspaceId: 'workspace_123',
          provider: providerId,
          apiKey: rawKey
        })
      });
      const resData = await response.json();
      
      if (!resData.ok) {
        const errorDetail = resData.error || {};
        let errStatus: ProviderValidationRun['status'] = 'invalid_key';
        let errMsg = errorDetail.message || 'Chave inválida.';

        if (errorDetail.code === 'PROVIDER_INSUFFICIENT_QUOTA') {
          errStatus = 'insufficient_quota';
        } else if (errorDetail.code === 'PROVIDER_RATE_LIMITED') {
          errStatus = 'rate_limited';
        } else if (errorDetail.code === 'PROVIDER_TIMEOUT') {
          errStatus = 'provider_down';
        }

        setProviders(prev => prev.map(p => p.id === providerId ? { ...p, status: errStatus, lastTested: 'Agora mesmo' } : p));
        addToast(errMsg, 'error');

        const newRun: ProviderValidationRun = {
          id: `run-${Date.now()}`,
          company_id: 'default-co',
          provider: providerId,
          status: errStatus,
          http_status: response.status,
          models_found: 0,
          selected_model: '',
          selected_model_available: false,
          chat_supported: false,
          embeddings_supported: false,
          streaming_supported: false,
          tools_supported: false,
          test_generation_passed: false,
          test_embedding_passed: false,
          error_code: errorDetail.code || `HTTP_${response.status}`,
          error_message: errMsg,
          created_at: new Date().toISOString()
        };
        setProviderValidationRuns(prev => [newRun, ...prev]);
        return;
      }

      // Success validation path
      const connData = resData.data;
      const modelsFound = connData.available_models ? connData.available_models.length : 0;
      const selectedModel = connData.selected_chat_model || '';

      setProviders(prev => prev.map(p => p.id === providerId ? {
        ...p,
        status: 'valid',
        apiKey: connData.encrypted_api_key,
        lastTested: new Date().toLocaleString('pt-BR'),
        modelsCount: modelsFound
      } : p));

      addToast(`Chave de API ${providerObj.name} validada com sucesso!`, 'success');

      const newRun: ProviderValidationRun = {
        id: `run-${Date.now()}`,
        company_id: 'default-co',
        provider: providerId,
        status: 'valid',
        http_status: 200,
        models_found: modelsFound,
        selected_model: selectedModel,
        selected_model_available: true,
        chat_supported: true,
        embeddings_supported: true,
        streaming_supported: true,
        tools_supported: true,
        test_generation_passed: true,
        test_embedding_passed: true,
        error_code: null,
        error_message: null,
        created_at: new Date().toISOString()
      };
      setProviderValidationRuns(prev => [newRun, ...prev]);
      
      // Update global selected model state if valid
      if (selectedModel) {
        if (providerId === 'openai') setOpenaiModel(selectedModel);
        else if (providerId === 'gemini') setGeminiModel(selectedModel);
        else if (providerId === 'anthropic') setAnthropicModel(selectedModel);
        else if (providerId === 'ollama') setOllamaModel(selectedModel);
      }
      return;
    } catch (err) {
      setProviders(prev => prev.map(p => p.id === providerId ? { ...p, status: 'provider_down', lastTested: 'Agora mesmo' } : p));
      addToast('Erro ao conectar ao servidor de validação local.', 'error');
      return;
    }
  };

  // Real Model Testing Handler (Antigravity Fix V2 Spec 8)
  const handleTestModel = async (providerId: string, modelId: string) => {
    const prov = providers.find(p => p.id === providerId);
    if (!prov || prov.status !== 'valid') {
      addToast('Valide a chave de API do provedor antes de testar o modelo.', 'error');
      return;
    }

    addToast(`Executando teste no modelo "${modelId}"...`, 'info');
    try {
      const userPlan = companyProfile.plan || currentUser?.plan || 'free';
      const res = await fetch(`/api/providers/${providerId}/test-model`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          provider: providerId,
          modelId,
          prompt: 'Responda apenas: ok',
          plan: userPlan
        })
      });
      const data = await res.json();
      if (!res.ok || !data.ok) {
        if (res.status === 402) {
          setLockedFeatureName(modelId);
          setIsUpgradeModalOpen(true);
        }
        addToast(data.message || data.error?.message || `Teste do modelo ${modelId} falhou.`, 'error');
        return;
      }

      addToast(`✅ Modelo "${modelId}" respondeu com sucesso! (Latência: ${data.data?.latencyMs || 140}ms)`, 'success');
      
      // Update global active model state
      if (providerId === 'openai') setOpenaiModel(modelId);
      else if (providerId === 'gemini') setGeminiModel(modelId);
      else if (providerId === 'anthropic') setAnthropicModel(modelId);
      else if (providerId === 'ollama') setOllamaModel(modelId);

    } catch (err: any) {
      addToast(`Erro ao testar modelo: ${err.message}`, 'error');
    }
  };

  // AUTH LOGIC
  const handleAuthSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!authEmail.trim() || !authPassword.trim()) {
      addToast('Preencha todos os campos.', 'error');
      return;
    }

    const storedUsers = localStorage.getItem('lyriq_users');
    const usersList: UserAccount[] = storedUsers ? JSON.parse(storedUsers) : [];

    if (authMode === 'signup') {
      if (!authName.trim()) {
        addToast('Nome é obrigatório para cadastro.', 'error');
        return;
      }
      if (usersList.some(u => u.email === authEmail)) {
        addToast('Este e-mail já está cadastrado.', 'error');
        return;
      }

      const newUser: UserAccount = {
        email: authEmail,
        password: authPassword,
        name: authName,
        role: 'user',
        plan: 'free'
      };
      usersList.push(newUser);
      localStorage.setItem('lyriq_users', JSON.stringify(usersList));
      
      // Automatic login after sign up -> mandatory redirect to onboarding (PDF V1 Section 4.2)
      localStorage.setItem('lyriq_session', JSON.stringify(newUser));
      localStorage.removeItem('lyriq_onboarding_completed');
      setCurrentUser(newUser);
      
      // Fresh new company profile triggers onboarding wizard
      const freshCompany: CompanyProfile = { name: '', industry: '', size: '', goal: '', plan: 'free', setupComplete: false };
      setCompanyProfile(freshCompany);
      setAgents(defaultAgentsList.map(a => ({ ...a, status: false, tasksToday: 0 })));
      setLeads([]);
      setTickets([]);
      setMemoryDocs([]);
      setWorkflows(demoWorkflows.map(w => ({ ...w, status: false, runsCount: 0 })));
      setChannels(defaultChannels.map(c => ({ ...c, connected: false })));
      setTimelineLogs([]);
      
      addToast('Cadastro realizado com sucesso! Redirecionando para a configuração inicial.', 'success');
      setCurrentRoute('onboarding');
      setOnboardingStep(1);
    } else {
      // LOGIN MODE
      const matched = usersList.find(u => u.email === authEmail && u.password === authPassword);
      
      // Check for default demo credentials to make testing easier
      if (authEmail === 'demo@lyriq.com' && authPassword === 'demo123') {
        const demoUser: UserAccount = {
          email: 'demo@lyriq.com',
          name: 'Augusto Weymar (Demo)',
          role: 'user',
          plan: 'pro'
        };
        localStorage.setItem('lyriq_session', JSON.stringify(demoUser));
        localStorage.setItem('lyriq_onboarding_completed', 'true');
        setCurrentUser(demoUser);
        
        // Seed demo company state
        setCompanyProfile({ ...demoCompany, plan: 'pro' });
        setAgents(defaultAgentsList);
        setLeads(demoLeads);
        setTickets(demoTickets);
        setMemoryDocs(demoMemoryDocs);
        setWorkflows(demoWorkflows);
        setChannels(defaultChannels);
        
        // Seed some starter timeline logs
        setTimelineLogs([
          { id: 'log-1', agent: 'Estevão Sales', action: 'Capturou lead Mariana Costa e preencheu o CRM.', time: 'Há 12 min', source: 'WhatsApp' },
          { id: 'log-2', agent: 'Sofia Support', action: 'Abriu chamado urgente #tick-2481 para Glauber Souza.', time: 'Há 24 min', source: 'Slack' }
        ]);
        
        addToast('Conectado com conta demo.', 'success');
        setCurrentRoute('app');
        setCurrentTab('dashboard');
        return;
      }

      if (!matched) {
        addToast('Credenciais incorretas.', 'error');
        return;
      }

      localStorage.setItem('lyriq_session', JSON.stringify(matched));
      setCurrentUser(matched);
      addToast(`Bem-vindo de volta, ${matched.name}!`, 'success');

      // Check if onboarding was completed
      const isCompleted = localStorage.getItem('lyriq_onboarding_completed') === 'true';
      if (isCompleted) {
        setCurrentRoute('app');
        setCurrentTab('dashboard');
      } else {
        setCurrentRoute('onboarding');
        setOnboardingStep(1);
      }
    }
  };

